@pytest.mark.parametrize("timing", ["settle", "timed"]) @pytest.mark.parametrize("concurrency", ["serial", "per_device"]) def test_placed_batches_values_all_gradients_continuation(timing, concurrency, monkeypatch): torch.manual_seed(814) reference, placed = models(timing, concurrency) import tide.region_batch as batching original = batching.evaluate_regions seen = []
