@pytest.mark.parametrize("sharing,memory,timing,partition", [ ("independent", "K", "settle", "group"), ("region_shared", "X", "settle", "group"), ("layer_shared", "X", "timed", "group"), ("region_shared", "X", "timed", "mixed"), ]) def test_region_batch_values_vjp_and_private_continuation(sharing, memory, timing, partition): torch.manual_seed(328) cfg = ModelConfig(topology=TopologyConfig(kind="multiscale", profile="compact-5-dd4", n=2, hubs=1, timing=timing, partition=partition), d=64, memory=memory, sharing=sharing, attention_backend="math") serial, batched = TideModel(cfg).double(), TideModel(replace(cfg, region_batch_size=4)).double() batched.load_state_dict(serial.state_dict()) x = torch.randn(2, 4, 64, dtype=torch.float64) results, gradients = [], [] for model in (serial, batched): inp = x.clone().requires_grad_() a = model(inp[:, :2], record_work=True) b = model(inp[:, 2:], a.state, record_work=True) results.append((a, b)) loss = a.readout().square().mean() + b.readout().square().mean() if timing == "timed": loss = loss + model.flush(b.state).readout().square().mean() loss.backward() gradients.append([inp.grad] + [p.grad for p in model.parameters()]) for ra, rb in zip(*results): > torch.testing.assert_close(ra.values, rb.values, rtol=2e-8, atol=2e-8) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 320 / 512 (62.5%) E Greatest absolute difference: 0.0008677214054939597 at index (0, 0, 0, 37) (up to 2e-08 allowed) E Greatest relative difference: 0.3021902156024593 at index (0, 0, 0, 15) (up to 2e-08 allowed)
